{
  "name": "MPI SENTIO晶圆探针台",
  "name_en": "MPI SENTIO wafer prober",
  "manufacturer": "MPI Corporation",
  "description": "这是一类用于半导体晶圆测试的自动或半自动探针台系统，可对晶圆卡盘进行XY、Z和旋转定位，并支持接触/分离高度控制、真空吸附、晶圆地图步进与可选热卡盘功能。该设备常用于晶圆级电学测量、器件表征、失效分析以及带有自动装载、显微镜或硅光子对准模块的测试流程。",
  "description_en": "This is an automatic or semi-automatic wafer prober used for semiconductor wafer testing. It provides XY, Z, and rotational chuck positioning, contact/separation height control, vacuum holding, wafer map stepping, and optional thermal chuck capability. It is commonly used for wafer-level electrical measurements, device characterization, failure analysis, and test workflows with optional auto-loading, microscope, or silicon photonics alignment modules.",
  "tag_hints": [
    "wafer probing",
    "semiconductor test",
    "motorized chuck positioning",
    "wafer map stepping",
    "thermal chuck",
    "probe station automation",
    "vacuum chuck",
    "silicon photonics alignment"
  ],
  "actions": [
    {
      "action_name": "auto-write",
      "description": "向探针台发送原始远程命令。",
      "description_en": "Send a raw remote command to the prober."
    },
    {
      "action_name": "auto-read",
      "description": "读取探针台返回的原始响应。",
      "description_en": "Read a raw response returned by the prober."
    },
    {
      "action_name": "auto-status_get_prop",
      "description": "获取指定状态属性。",
      "description_en": "Get a specified status property."
    },
    {
      "action_name": "auto-status_set_prop",
      "description": "设置指定状态属性。",
      "description_en": "Set a specified status property."
    },
    {
      "action_name": "auto-status_get_machine_id",
      "description": "获取设备机器标识。",
      "description_en": "Get the machine identifier."
    },
    {
      "action_name": "auto-status_get_version",
      "description": "获取系统版本信息。",
      "description_en": "Get the system version information."
    },
    {
      "action_name": "auto-status_get_machine_status",
      "description": "获取设备运行状态标志。",
      "description_en": "Get the machine status flags."
    },
    {
      "action_name": "auto-status_show_message",
      "description": "在设备界面显示消息对话框供操作员确认。",
      "description_en": "Show a message dialog on the system for operator interaction."
    },
    {
      "action_name": "auto-set_chuck_speed",
      "description": "设置卡盘移动速度。",
      "description_en": "Set the chuck movement speed."
    },
    {
      "action_name": "auto-set_soft_contact",
      "description": "启用或禁用软接触模式。",
      "description_en": "Enable or disable soft contact mode."
    },
    {
      "action_name": "auto-set_vacuum",
      "description": "打开或关闭卡盘真空吸附。",
      "description_en": "Turn the chuck vacuum on or off."
    },
    {
      "action_name": "auto-move_chuck_center",
      "description": "将卡盘移动到当前站点中心位置。",
      "description_en": "Move the chuck to the center position of the current site."
    },
    {
      "action_name": "auto-move_chuck_contact",
      "description": "将卡盘移动到接触高度。",
      "description_en": "Move the chuck to the contact height."
    },
    {
      "action_name": "auto-move_chuck_home",
      "description": "将卡盘移动到当前站点的原点位置。",
      "description_en": "Move the chuck to the home position of the current site."
    },
    {
      "action_name": "auto-move_chuck_separation",
      "description": "将卡盘移动到分离高度。",
      "description_en": "Move the chuck to the separation height."
    },
    {
      "action_name": "auto-move_chuck_load",
      "description": "将卡盘移动到装载位置。",
      "description_en": "Move the chuck to the load position."
    },
    {
      "action_name": "auto-set_chuck_separation_gap",
      "description": "设置卡盘分离间隙。",
      "description_en": "Set the chuck separation gap."
    },
    {
      "action_name": "auto-stop_chuck_theta",
      "description": "停止卡盘旋转运动。",
      "description_en": "Stop chuck rotation."
    },
    {
      "action_name": "auto-stop_chuck_xyz",
      "description": "停止卡盘XYZ运动。",
      "description_en": "Stop chuck movement in XYZ."
    },
    {
      "action_name": "auto-has_scope_xyz",
      "description": "查询系统是否配备电动显微镜XYZ轴。",
      "description_en": "Check whether the system has motorized microscope XYZ axes."
    },
    {
      "action_name": "auto-has_scope_z",
      "description": "查询系统是否配备电动显微镜Z轴。",
      "description_en": "Check whether the system has a motorized microscope Z axis."
    },
    {
      "action_name": "auto-status_get_chuck_temp",
      "description": "获取卡盘温度。",
      "description_en": "Get the chuck temperature."
    },
    {
      "action_name": "auto-map_get_prop",
      "description": "获取指定晶圆地图属性。",
      "description_en": "Get a specified wafer map property."
    },
    {
      "action_name": "auto-map_step_die",
      "description": "步进到指定行列的晶粒位置。",
      "description_en": "Step to the die at a specified row and column."
    },
    {
      "action_name": "auto-map_step_die_seq",
      "description": "按步进序列移动到指定晶粒或子站点。",
      "description_en": "Step to a specified die or subsite in the stepping sequence."
    },
    {
      "action_name": "auto-map_step_next_die",
      "description": "步进到路线中的下一颗晶粒。",
      "description_en": "Step to the next die in the routing sequence."
    },
    {
      "action_name": "auto-map_step_previous_die",
      "description": "步进到路线中的上一颗晶粒。",
      "description_en": "Step to the previous die in the routing sequence."
    },
    {
      "action_name": "auto-map_subsite_get_num",
      "description": "获取子站点数量。",
      "description_en": "Get the number of subsites."
    },
    {
      "action_name": "auto-map_subsite_step",
      "description": "步进到指定子站点。",
      "description_en": "Step to a specified subsite."
    },
    {
      "action_name": "auto-map_get_num_dies",
      "description": "获取晶圆地图中的晶粒数量。",
      "description_en": "Get the number of dies in the wafer map."
    },
    {
      "action_name": "auto-map_die_get_current_index",
      "description": "获取当前晶粒索引信息。",
      "description_en": "Get the current die index information."
    },
    {
      "action_name": "auto-map_die_get_current_subsite",
      "description": "获取当前子站点索引。",
      "description_en": "Get the current subsite index."
    },
    {
      "action_name": "auto-map_get_die_seq",
      "description": "获取当前晶粒序列号。",
      "description_en": "Get the current die sequence number."
    },
    {
      "action_name": "auto-map_get_num_rows",
      "description": "获取晶圆地图行数。",
      "description_en": "Get the number of rows in the wafer map grid."
    },
    {
      "action_name": "auto-map_get_num_cols",
      "description": "获取晶圆地图列数。",
      "description_en": "Get the number of columns in the wafer map grid."
    },
    {
      "action_name": "auto-map_get_grid_origin",
      "description": "获取晶圆地图网格原点。",
      "description_en": "Get the wafer map grid origin."
    },
    {
      "action_name": "auto-map_path_get_die",
      "description": "根据序列号查询晶粒行列位置。",
      "description_en": "Query the die row and column by sequence number."
    },
    {
      "action_name": "auto-light_off_at_contact",
      "description": "定义卡盘到达接触高度时是否关闭照明。",
      "description_en": "Define whether illumination is turned off at contact height."
    },
    {
      "action_name": "auto-light_on_at_separation",
      "description": "定义卡盘到达分离高度时是否开启照明。",
      "description_en": "Define whether illumination is turned on at separation height."
    },
    {
      "action_name": "auto-loader_scan_station",
      "description": "扫描装载站的晶圆在位状态。",
      "description_en": "Scan wafer presence status at a loader station."
    },
    {
      "action_name": "auto-move_positioner_xy",
      "description": "移动电动定位器的XY位置。",
      "description_en": "Move a motorized positioner in XY."
    },
    {
      "action_name": "auto-siph_move_hover",
      "description": "将硅光子定位器移动到悬停高度。",
      "description_en": "Move the silicon photonics positioner to the hover height."
    },
    {
      "action_name": "auto-siph_move_separation",
      "description": "将硅光子定位器移动到分离高度。",
      "description_en": "Move the silicon photonics positioner to the separation height."
    },
    {
      "action_name": "auto-siph_fast_alignment",
      "description": "启动硅光子定位器快速对准。",
      "description_en": "Start fast alignment for the silicon photonics positioner."
    },
    {
      "action_name": "auto-siph_gradient_search",
      "description": "启动硅光子定位器梯度搜索对准。",
      "description_en": "Start gradient-search alignment for the silicon photonics positioner."
    },
    {
      "action_name": "auto-siph_get_intensity",
      "description": "获取硅光子对准强度值。",
      "description_en": "Get the silicon photonics alignment intensity value."
    },
    {
      "action_name": "auto-siph_power_calibration",
      "description": "执行硅光子功率校准并返回功率值。",
      "description_en": "Perform silicon photonics power calibration and return the power value."
    },
    {
      "action_name": "auto-siph_move_origin",
      "description": "将硅光子定位器移动到原点位置。",
      "description_en": "Move the silicon photonics positioner to the origin position."
    },
    {
      "action_name": "auto-siph_set_alignment",
      "description": "设置硅光子快速对准所启用的搜索模式。",
      "description_en": "Set the enabled search modes for silicon photonics fast alignment."
    },
    {
      "action_name": "auto-siph_get_alignment",
      "description": "获取硅光子快速对准的搜索模式设置。",
      "description_en": "Get the search mode settings for silicon photonics fast alignment."
    }
  ]
}

